CREATE Proc [dbo].[ReportIssNoWiseIssuanceReport] @IssNoId as nvarchar(50),@Login as nvarchar(max)as select @Login as LoginUser,ism.Date,ism.IssNo as Category ,s.Store,Un.Unit as Branch,c.Category,sc.Subcategory,i.Item,i.itemid,U.Unit as PackingType,iu.RecpFactor as UnitQty,db.DSNo, (Select Distinct(Unit) from unit  where UId=issd.Unit) as UnitType, issd.Qty as IssuedQty,issd.Rate as UnitPrice ,dp.department_name as 'IssNo1' from IssuanceMaster_Store ism  inner join IssuanceDetail_Store issd on ism.IssId=issd.IssId inner join Store s on ism.SId=s.SId inner join Branch b on ism.BRId=b.BRId inner join DepartmentPos dp on dp.BRId = b.BRId and ism.DId = dp.id left join DemandSheetMaster_Branch db on db.DSId=issd.DSId inner join Item i on issd.ItemId=i.ItemId inner join Subcategory sc on i.SBId = sc.SBId inner join Category c on sc.CId=c.CId inner join ItemUnit iu on i.ItemId=iu.ItemId inner join Unit U on iu.PkUnit=U.UId inner join Unit Un on iu.PurUnit=Un.UId inner join Split(@IssNoId,',') sp on sp.items =ism.IssId group by issd.Rate ,ism.Date,ism.IssNo,Un.Unit,c.Category,sc.Subcategory,i.Item, U.Unit,iu.RecpFactor,db.DSNo,issd.Unit,issd.Qty,i.ItemId,s.Store,s.SId,iu.IssFactor,dp.department_name order by ism.IssNo asc